const markets = [
  { id: 'market_us_tx_dallas', country: 'US', state: 'TX', city: 'Dallas', priority: 1, target: 15, query: 'plumbing contractor Dallas TX' },
  { id: 'market_us_tx_austin', country: 'US', state: 'TX', city: 'Austin', priority: 2, target: 15, query: 'residential plumber Austin TX' }
];
return markets.map(m => ({ json: m }));

const places = $json.places || [];
const market = $('Load Next Market Queue').item.json;
const out = [];
for (const p of places) {
  if (p.businessStatus === 'CLOSED_PERMANENTLY' || p.businessStatus === 'CLOSED_TEMPORARILY') continue;
  out.push({
    json: {
      placeId: p.id,
      businessName: p.displayName?.text || 'Unknown Business',
      formattedAddress: p.formattedAddress || '',
      city: market.city,
      state: market.state,
      country: market.country,
      phone: p.nationalPhoneNumber || '',
      website: p.websiteUri || '',
      types: p.types || []
    }
  });
}
return out;

const items = $input.all();
const seen = new Set();
const unique = [];
for (const item of items) {
  const p = item.json;
  const key = p.placeId || (p.businessName + '_' + p.city);
  if (!seen.has(key)) {
    seen.add(key);
    unique.push(item);
  }
}
return unique;

const p = $json;
let score = 0;
const reasons = [];
const lowerName = (p.businessName || '').toLowerCase();

if (lowerName.includes('plumb') || (p.types || []).includes('plumber')) {
  score += 2;
  reasons.push('Core plumbing service verified (+2)');
}
if (!lowerName.includes('group') && !lowerName.includes('franchise')) {
  score += 2;
  reasons.push('Independent trade business signal (+2)');
}
if (p.phone) {
  score += 2;
  reasons.push('Direct dispatch phone available (+2)');
}
score += 2;
reasons.push('Quote-to-invoice workflow upgrade potential (+2)');
if (p.website) {
  score += 1;
  reasons.push('Active public website presence (+1)');
}

score = Math.min(10, score);
let priority = 'REJECT';
if (score >= 9) priority = 'P0';
else if (score >= 7) priority = 'P1';
else if (score >= 5) priority = 'P2';

return [{
  json: {
    ...p,
    score,
    priority,
    scoreReasons: reasons.join('; '),
    source: 'Google Places + Web',
    discoveredAt: new Date().toISOString()
  }
}];
